export type Fund = {
  id: string
  projectId: string
  name: string
  totalValue: number
  allocatedValue: number
  remainingValue: number
  currency: string
  status: 'active' | 'locked' | 'closed'
  createdAt: string
}

export type WalletBalance = {
  userId: string
  tenantId: string
  balance: number
  currency: string
  lockedBalance: number
  updatedAt: string
}

export type CreditLedgerEntry = {
  id: string
  userId: string
  tenantId: string
  type: 'credit' | 'debit' | 'lock' | 'unlock'
  amount: number
  currency: string
  description: string
  referenceId?: string
  referenceType?: string
  createdAt: string
}
